<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { eliminarProgramacion, guardarProgramacion, listarEvidencias, listarIncidencias, listarProgramaciones } from '../services/programaciones'
import type { DetalleProgramacion, EvidenciaProgramacion, IncidenciaProgramacion, OpcionProgramacion, Programacion, ProgramacionPayload } from '../interfaces/programaciones.interface'
const records=ref<Programacion[]>([]),units=ref<OpcionProgramacion[]>([]),drivers=ref<OpcionProgramacion[]>([]),districts=ref<OpcionProgramacion[]>([]),points=ref<OpcionProgramacion[]>([]),reasons=ref<Record<number,string>>({}),incidents=ref<IncidenciaProgramacion[]>([]),evidence=ref<EvidenciaProgramacion[]>([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detailModal=ref<'incidencias'|'evidencias'|null>(null),editing=ref<number|null>(null),current=ref<Programacion|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),summary=reactive({unidades:0,con_incidencias:0,con_evidencias:0})
const filters=reactive({criterio:'',fecha_desde:'',fecha_hasta:'',motivo:'',incidencias:''})
const form=reactive<ProgramacionPayload>({fecha:'',motivo_id:null,observacion:'',r1_desde:'08:00',r1_hasta:'12:00',r2_desde:'14:00',r2_hasta:'17:00',cisternas:[]})
async function load(target=1){loading.value=true;error.value='';try{const r=await listarProgramaciones(filters,target);records.value=r.data;units.value=r.cisternas;drivers.value=r.conductores;districts.value=r.distritos;points.value=r.puntos_abastecimiento;reasons.value=r.motivos;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;Object.assign(summary,r.resumen)}catch(e){error.value=message(e)}finally{loading.value=false}}
function blankDetail():DetalleProgramacion{return{id:undefined,cisterna_id:null,placa:'',conductor_id:null,conductor:'',distrito_id:null,distrito:'',punto_abastecimiento_id:null,punto_abastecimiento:'',ruta:'',numero_vueltas:1}}
function open(item?:Programacion){editing.value=item?.id??null;Object.assign(form,item?{fecha:item.fecha,motivo_id:item.motivo_id,observacion:item.observacion,r1_desde:item.r1_desde,r1_hasta:item.r1_hasta,r2_desde:item.r2_desde,r2_hasta:item.r2_hasta,cisternas:item.detalles.map(d=>({...d}))}:{fecha:new Date().toISOString().slice(0,10),motivo_id:null,observacion:'',r1_desde:'08:00',r1_hasta:'12:00',r2_desde:'14:00',r2_hasta:'17:00',cisternas:[blankDetail()]});error.value='';modal.value=true}
function unitChanged(row:DetalleProgramacion){row.placa=units.value.find(x=>x.id===row.cisterna_id)?.placa??''}function removeRow(index:number){form.cisternas.splice(index,1)}
async function save(){if(!form.fecha||!form.motivo_id||!form.observacion.trim()||!form.r1_desde||!form.r1_hasta||!form.r2_desde||!form.r2_hasta){error.value='Complete la fecha, horarios, motivo y observación.';return}if(form.r1_hasta<=form.r1_desde||form.r2_hasta<=form.r2_desde){error.value='La hora final de cada rango debe ser posterior a la inicial.';return}if(!form.cisternas.length){error.value='Debe agregar al menos una cisterna.';return}if(form.cisternas.some(x=>!x.cisterna_id||!x.conductor_id||!x.distrito_id||!x.punto_abastecimiento_id||!x.ruta.trim()||x.numero_vueltas<1)){error.value='Complete unidad, conductor, distrito, punto, ruta y vueltas en cada asignación.';return}saving.value=true;try{await guardarProgramacion(form,editing.value??undefined);modal.value=false;success.value=`Programación ${editing.value?'actualizada':'registrada'} correctamente.`;await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:Programacion){if(!confirm(`¿Eliminar la programación #${item.id}?`))return;try{await eliminarProgramacion(item.id);success.value='Programación eliminada.';await load(page.value)}catch(e){error.value=message(e)}}
async function showDetails(item:Programacion,type:'incidencias'|'evidencias'){current.value=item;loading.value=true;try{if(type==='incidencias')incidents.value=await listarIncidencias(item.id);else evidence.value=await listarEvidencias(item.id);detailModal.value=type}catch(e){error.value=message(e)}finally{loading.value=false}}
function clearFilters(){Object.assign(filters,{criterio:'',fecha_desde:'',fecha_hasta:'',motivo:'',incidencias:''});load(1)}const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Gestión de Cisternas / Programación</nav><header class="hero"><div class="mark">PR</div><div><small>DANA · GESTIÓN DE CISTERNAS</small><h1>Programación de cisternas</h1><p>Planifica horarios, unidades, conductores, rutas y puntos de abastecimiento.</p></div><button @click="open()">+ Registrar programación</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="summary"><article><small>PROGRAMACIONES</small><b>{{total}}</b></article><article><small>UNIDADES ASIGNADAS</small><b>{{summary.unidades}}</b></article><article><small>CON INCIDENCIAS</small><b>{{summary.con_incidencias}}</b></article><article><small>CON EVIDENCIAS</small><b>{{summary.con_evidencias}}</b></article></section><form class="filters" @submit.prevent="load(1)"><label>Descripción<input v-model.trim="filters.criterio" placeholder="Placa, VIN o N°"></label><label>Desde<input v-model="filters.fecha_desde" type="date"></label><label>Hasta<input v-model="filters.fecha_hasta" type="date"></label><label>Motivo<select v-model="filters.motivo"><option value="">Todos</option><option v-for="(name,key) in reasons" :key="key" :value="String(key)">{{name}}</option></select></label><label>Incidencias<select v-model="filters.incidencias"><option value="">Todas</option><option value="1">Con incidencias</option><option value="0">Sin incidencias</option></select></label><button>Buscar</button><button type="button" class="soft" @click="clearFilters">Limpiar</button></form><div v-if="loading" class="empty">Cargando programaciones…</div><div v-else-if="!records.length" class="empty">No se encontraron programaciones.</div><section v-else class="cards"><article v-for="item in records" :key="item.id"><header><div><small>PROGRAMACIÓN #{{item.id}}</small><h2>{{new Date(item.fecha+'T00:00:00').toLocaleDateString('es-PE')}}</h2></div><span :class="{alert:item.incidencias_count}">{{item.incidencias_count?`${item.incidencias_count} incidencia(s)`:'Sin incidencias'}}</span></header><p class="reason">{{item.motivo}}</p><div class="schedule"><b>{{item.r1_desde}} — {{item.r1_hasta}}</b><b>{{item.r2_desde}} — {{item.r2_hasta}}</b></div><ul><li v-for="(row,index) in item.detalles" :key="row.id??index"><b>{{row.placa}}</b><span>{{row.conductor}}</span><small>{{row.distrito}} · {{row.numero_vueltas}} vuelta(s)</small></li></ul><p class="note">{{item.observacion}}</p><footer><button :disabled="item.vencida" @click="open(item)">Modificar</button><button v-if="item.incidencias_count" class="dark" @click="showDetails(item,'incidencias')">Incidencias</button><button v-if="item.evidencias_count" class="purple" @click="showDetails(item,'evidencias')">Evidencias</button><button class="delete" :disabled="item.vencida||item.vinculada_interrupcion" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>PLANIFICACIÓN OPERATIVA</small><h2>{{editing?'Modificar':'Registrar'}} programación</h2></div><button type="button" @click="modal=false">×</button></header><div class="fields head-fields"><label>Fecha *<input v-model="form.fecha" type="date"></label><label>Motivo *<select v-model="form.motivo_id"><option :value="null">Seleccione</option><option v-for="(name,key) in reasons" :key="key" :value="Number(key)">{{name}}</option></select></label><label>Rango 1 desde *<input v-model="form.r1_desde" type="time"></label><label>Rango 1 hasta *<input v-model="form.r1_hasta" type="time"></label><label>Rango 2 desde *<input v-model="form.r2_desde" type="time"></label><label>Rango 2 hasta *<input v-model="form.r2_hasta" type="time"></label><label class="wide">Observación *<textarea v-model="form.observacion" rows="2" maxlength="300"></textarea></label></div><div class="detail-title"><h3>Cisternas asignadas</h3><button type="button" @click="form.cisternas.push(blankDetail())">+ Agregar unidad</button></div><article v-for="(row,index) in form.cisternas" :key="index" class="assignment"><div class="fields"><label>Unidad *<select v-model="row.cisterna_id" @change="unitChanged(row)"><option :value="null">Seleccione</option><option v-for="unit in units" :key="unit.id" :value="unit.id">{{unit.placa||unit.nombre}} · {{unit.capacidad}} m³</option></select></label><label>Conductor *<select v-model="row.conductor_id"><option :value="null">Seleccione</option><option v-for="driver in drivers" :key="driver.id" :value="driver.id">{{driver.nombre}}</option></select></label><label>Distrito *<select v-model="row.distrito_id"><option :value="null">Seleccione</option><option v-for="district in districts" :key="district.id" :value="district.id">{{district.nombre}}</option></select></label><label>Punto de abastecimiento *<select v-model="row.punto_abastecimiento_id"><option :value="null">Seleccione</option><option v-for="point in points" :key="point.id" :value="point.id">{{point.nombre}}</option></select></label><label>Número de vueltas *<input v-model.number="row.numero_vueltas" type="number" min="1"></label><label class="wide">Ruta a seguir *<textarea v-model="row.ruta" rows="2" maxlength="1000"></textarea></label></div><button type="button" class="remove" @click="removeRow(index)">Quitar asignación</button></article><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar programación'}}</button></footer></form></div>
<div v-if="detailModal" class="backdrop" @mousedown.self="detailModal=null"><section class="dialog detail"><header><div><small>PROGRAMACIÓN #{{current?.id}}</small><h2>{{detailModal==='incidencias'?'Incidencias reportadas':'Evidencias registradas'}}</h2></div><button @click="detailModal=null">×</button></header><template v-if="detailModal==='incidencias'"><article v-for="item in incidents" :key="item.id"><b>{{item.placa}} · {{item.conductor}}</b><span>{{item.fecha}}</span><p>{{item.comentario}}</p><small>Ubicación: {{item.latitud}}, {{item.longitud}}</small><div><a v-for="img in item.imagenes" :key="img.id" :href="img.url" target="_blank">{{img.nombre}}</a></div></article><p v-if="!incidents.length">Sin incidencias.</p></template><template v-else><article v-for="item in evidence" :key="item.id"><b>{{item.placa}}</b><span>{{item.fecha}}</span><a :href="item.url" target="_blank">{{item.archivo}}</a></article><p v-if="!evidence.length">Sin evidencias.</p></template></section></div></div></template>
<style scoped>
.page{--accent:#e38b2f;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.summary small,.cards small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero button,.filters button,.dialog button,.pager button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.hero>button{margin-left:auto}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.summary{margin-top:10px;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.summary article{padding:11px;display:grid;border-radius:8px;background:#fff}.summary b{font-size:.85rem}.filters{margin-top:8px;padding:12px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label,.dialog label{display:grid;gap:4px;font-size:.47rem}.filters label:first-child{flex:1}.filters input,.filters select,.dialog input,.dialog select,.dialog textarea{box-sizing:border-box;padding:8px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.5rem}.soft{color:#64727a!important;background:#edf1f3!important}.empty{margin-top:9px;padding:45px;text-align:center;border-radius:9px;background:#fff;font-size:.58rem}.cards{margin-top:9px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.cards>article{padding:14px;border-top:4px solid #536d91;border-radius:9px;background:#fff}.cards header{display:flex;justify-content:space-between}.cards h2{margin:3px 0;font-size:.78rem}.cards header span{padding:4px 6px;align-self:start;border-radius:7px;color:#287055;background:#e4f5ed;font-size:.4rem}.cards header span.alert{color:#a26c18;background:#fff0ce}.reason{margin:8px 0;padding:7px;border-radius:5px;background:#edf2f6;font-size:.5rem;font-weight:700}.schedule{display:flex;gap:6px}.schedule b{flex:1;padding:6px;text-align:center;border-radius:5px;color:#536d91;background:#eaf0f7;font-size:.45rem}.cards ul{padding:0;list-style:none}.cards li{margin-top:5px;padding:6px;display:grid;grid-template-columns:auto 1fr;gap:2px 7px;border-left:3px solid var(--accent);background:#faf7f1;font-size:.45rem}.cards li small{grid-column:1/-1;color:#7d898f}.note{min-height:26px;color:#78858b;font-size:.44rem}.cards footer{display:flex;gap:4px}.cards footer button{flex:1;padding:7px;border:0;border-radius:5px;color:#79500b;background:#ffe7bd;font-size:.4rem}.cards .dark{color:#fff;background:#4a5861}.cards .purple{color:#fff;background:#76569b}.delete,.remove{color:#a23d43!important;background:#fde8e8!important}button:disabled{opacity:.4}.pager{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:10px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(900px,100%);max-height:94vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.fields{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.fields .wide{grid-column:1/-1}.detail-title{margin-top:12px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e2e8ea}.detail-title h3{font-size:.58rem}.detail-title button{padding:6px}.assignment{margin-top:8px;padding:10px;border-radius:7px;background:#f6f8f9}.assignment .fields{grid-template-columns:repeat(2,1fr)}.assignment>.remove{margin-top:7px;padding:6px}.dialog>footer{margin-top:14px;display:flex;justify-content:flex-end;gap:5px}.detail{width:min(650px,100%)}.detail article{padding:9px;display:grid;gap:3px;border-bottom:1px solid #e3e8ea;font-size:.48rem}.detail article span{color:#7c898f}.detail article p{margin:2px 0}.detail article a{margin-right:8px;color:#536d91}@media(max-width:900px){.hero,.filters{flex-wrap:wrap}.hero>button{margin-left:0}.summary,.cards,.fields,.assignment .fields{grid-template-columns:1fr}.fields .wide{grid-column:auto}.filters label{width:100%}}
</style>
